SELECT STATE 
FROM INV_VOUCHER 
WHERE COST_CENTER_TITLE = 'سیرجان';

SELECT * FROM INV_VOUCHER 
JOIN INV_VOUCHER_ITEM ON INV_VOUCHER.ID = INV_VOUCHER_ITEM.INVENTORY_VOUCHER_REF 
WHERE INV_VOUCHER_ITEM.SUPPLIER_TITLE LIKE '%آهن اسفنجی%' OR INV_VOUCHER_ITEM.DESCRIPTION LIKE '%آهن اسفنجی%';

SELECT * FROM INV_VOUCHER_ITEM 
JOIN INV_VOUCHER ON INV_VOUCHER.ID = INV_VOUCHER_ITEM.INVENTORY_VOUCHER_REF  
WHERE SL_TITLE LIKE '%آهن اسفنجی%' OR DESCRIPTION LIKE '%آهن اسفنجی%';

SELECT `CONTRACTOR_TITLE` 
FROM `INV_VOUCHER`
WHERE `TITLE` = 'دریافت ضایعات تولید' AND `STATE` = 'تایید شده';

SELECT COUNT(*) 
FROM INV_VOUCHER 
WHERE COST_CENTER_TITLE = 'مرکز نگهداری سیرجان' AND STATE = 'باطل شده' AND MONTH(DATE) = 4;

SELECT MAX(NUMBER) 
FROM INV_VOUCHER 
WHERE TITLE = 'خرید' AND SUPPLIER_TITLE LIKE '%DRI%' AND STATE = 'تایید شده';

SELECT SUPPLIER_TITLE 
FROM INV_VOUCHER 
WHERE DATE = CURDATE() - INTERVAL 1 DAY AND DESCRIPTION LIKE '%خرید لپ تاپ ASUS%' ;
